def solve(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited=[[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack=[(r,c)]
        while stack:
            x,y=stack.pop()
            if x<0 or x>=rows or y<0 or y>=cols:
                continue
            if visited[x][y] or grid[x][y]==0:
                continue
            visited[x][y]=True
            stack.extend([(x-1,y),(x+1,y),(x,y-1),(x,y+1)])
    count=0
    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and grid[i][j]==1:
                dfs(i,j)
                count+=1
    return count

