    Connections are 4-directional (up, down, left, right).
    """
    if not grid:
        return 0
    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    def bfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= m or y < 0 or y >= n:
                continue
            if visited[x][y] or grid[x][y] == 0:
                continue
            visited[x][y] = True
            stack.extend([(x-1, y), (x+1, y), (x, y-1), (x, y+1)])
