def solve(s=None):
    """Run-length encoding for any iterable.
    Returns a list of [item, count] pairs for consecutive equal items.
    If ``s`` is ``None`` or empty, returns an empty list.
    """
    if s is None:
        return []
    try:
        iterator = iter(s)
    except TypeError:
        # Not iterable
        return []
    # Get first element
    try:
        cur = next(iterator)
    except StopIteration:
        return []
    result = []
    cnt = 1
    for item in iterator:
        if item == cur:
            cnt += 1
        else:
            result.append([cur, cnt])
            cur = item
            cnt = 1
    result.append([cur, cnt])
    return result

