    for token in tokens:
        # Determine if token is an operator
        if token in ops:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division, truncate toward zero
                # Use int(a / b) for truncation toward zero (works for negative numbers)
                res = int(a / b)
            stack.append(res)
        else:
            # Operand: could be int, or numeric string
            if isinstance(token, int):
                stack.append(token)
            else:
                # Assume string representation of an integer
                stack.append(int(token))
    # After processing, the stack should have exactly one element
    return stack[0] if stack else 0

